function apiFetch(path,options={}){const headers=new Headers(options.headers||{}),token=localStorage.getItem(AUTH_TOKEN_KEY);if(token)headers.set('authorization',`Bearer ${token}`);return fetch(`${API_BASE}${path}`,{...options,headers})}
