let events,todos;try{events=JSON.parse(localStorage.getItem('illini-events'))||sampleEvents()}catch{events=sampleEvents()}try{todos=JSON.parse(localStorage.getItem('illini-todos'))||[]}catch{todos=[]}
function setSyncStatus(text){const el=$('#syncStatus');if(el)el.textContent=text}
function setPrivacyStatus(){const el=$('#privacyNote');if(!el)return;if(currentAccount&&cloudReady){el.textContent='Private to your account · Cloud sync on';return}el.textContent=(demoMode?'Demo schedule · ':'')+'Saved on this device · Sign in for cloud sync'}
async function pushCloudState(){if(!cloudReady||!currentAccount)return;setSyncStatus('Syncing…');try{const response=await apiFetch('/api/state',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({events,todos,preferences:{view,focus:fmtDate(focusDate),birthday}})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Sync failed');setSyncStatus('Synced across devices')}catch{setSyncStatus('Saved on device · retrying');clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>{cloudWrite=cloudWrite.then(pushCloudState)},5000)}}
function scheduleCloudSave(){if(!cloudReady)return;clearTimeout(cloudTimer);setSyncStatus('Changes pending…');cloudTimer=setTimeout(()=>{cloudWrite=cloudWrite.then(pushCloudState)},550)}
function save(){localStorage.setItem('illini-events',JSON.stringify(events));localStorage.setItem('illini-todos',JSON.stringify(todos));localStorage.setItem('illini-view',view);localStorage.setItem('illini-focus',fmtDate(focusDate));birthday?localStorage.setItem('illini-birthday',birthday):localStorage.removeItem('illini-birthday');scheduleCloudSave()}
function downloadText(filename,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),0)}
function exportJson(){const payload={version:1,exportedAt:new Date().toISOString(),events,todos,preferences:{view,focus:fmtDate(focusDate),birthday}};downloadText('illini-day-'+fmtDate(new Date())+'.json',JSON.stringify(payload,null,2),'application/json');toast('Backup downloaded')}
function icsEscape(value){return String(value??'').replace(/\\/g,'\\\\').replace(/;/g,'\\;').replace(/,/g,'\\,').replace(/\r?\n/g,'\\n')}
function icsDate(date,time){return String(date).replaceAll('-','')+'T'+String(time||'00:00').replace(':','')+'00'}
function exportIcs(){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Illini Day//UIUC Planner//','CALSCALE:GREGORIAN'];events.slice().sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start)).forEach(event=>{lines.push('BEGIN:VEVENT','UID:'+icsEscape(event.id)+'@illini-day','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART:'+icsDate(event.date,event.start),'DTEND:'+icsDate(event.date,event.end),'SUMMARY:'+icsEscape(event.title),'LOCATION:'+icsEscape(event.place));if(event.note)lines.push('DESCRIPTION:'+icsEscape(event.note));if(event.url)lines.push('URL:'+event.url);lines.push('END:VEVENT')});lines.push('END:VCALENDAR');downloadText('illini-day-'+fmtDate(new Date())+'.ics',lines.join('\r\n')+'\r\n','text/calendar');toast('Calendar file downloaded')}
function icsUnescape(value){return String(value??'').replace(/\\n/g,'\n').replace(/\\,/g,',').replace(/\\;/g,';').replace(/\\\\/g,'\\')}
function parseIcsDate(value){const raw=String(value||'').split(':').pop().replace(/[^0-9T]/g,'');if(raw.length>=15&&raw.includes('T'))return {date:raw.slice(0,4)+'-'+raw.slice(4,6)+'-'+raw.slice(6,8),time:raw.slice(9,11)+':'+raw.slice(11,13)};if(raw.length>=8)return {date:raw.slice(0,4)+'-'+raw.slice(4,6)+'-'+raw.slice(6,8),time:null};return null}
function parseIcs(text){const lines=String(text).replace(/\r\n/g,'\n').split('\n'),unfolded=[];lines.forEach(line=>/^[ \t]/.test(line)&&unfolded.length?unfolded[unfolded.length-1]+=line.slice(1):unfolded.push(line));const parsed=[];let current=null;unfolded.forEach(line=>{if(line==='BEGIN:VEVENT'){current={};return}if(line==='END:VEVENT'){if(current?.DTSTART&&current.SUMMARY){const start=parseIcsDate(current.DTSTART),end=parseIcsDate(current.DTEND),allDay=!start?.time;if(start)parsed.push({id:'ics-'+uid(),date:start.date,start:start.time||'09:00',end:end?.time||'10:00',title:icsUnescape(current.SUMMARY),place:icsUnescape(current.LOCATION||'Anywhere'),type:'Campus',note:icsUnescape(current.DESCRIPTION||''),url:current.URL||'',allDay})}current=null;return}if(!current)return;const index=line.indexOf(':');if(index<0)return;const key=line.slice(0,index).split(';')[0];current[key]=(current[key]?current[key]+'\n':'')+line.slice(index+1)});return parsed}
async function importDataFile(file){const text=await file.text();let importedEvents=[],importedTodos=[],preferences={};if(file.name.toLowerCase().endsWith('.ics')||text.includes('BEGIN:VCALENDAR'))importedEvents=parseIcs(text);else{const payload=JSON.parse(text);if(!Array.isArray(payload.events))throw new Error('This backup does not contain a valid events list.');importedEvents=payload.events.filter(event=>event&&/^\d{4}-\d{2}-\d{2}$/.test(event.date)&&/^\d{2}:\d{2}$/.test(event.start)&&/^\d{2}:\d{2}$/.test(event.end)&&event.title).map(event=>({...event,id:event.id||uid()}));importedTodos=Array.isArray(payload.todos)?payload.todos:[];preferences=payload.preferences||{}}if(!importedEvents.length&&!importedTodos.length)throw new Error('No usable events or tasks were found.');const taskCount=importedTodos.length?' and '+importedTodos.length+' task'+(importedTodos.length===1?'':'s'):'';if(!window.confirm('Replace this device schedule with '+importedEvents.length+' event'+(importedEvents.length===1?'':'s')+taskCount+'?'))return;events=importedEvents; todos=importedTodos; demoMode=false;localStorage.setItem(DEMO_MODE_KEY,'0');localStorage.setItem(WELCOME_KEY,'1');if(['agenda','day','week','month','year'].includes(preferences.view))view=preferences.view;if(/^\d{4}-\d{2}-\d{2}$/.test(preferences.focus||'')){focusDate=atNoon(preferences.focus);miniDate=new Date(focusDate)}birthday=/^\d{4}-\d{2}-\d{2}$/.test(preferences.birthday||'')?preferences.birthday:'';render();toast('Imported '+importedEvents.length+' event'+(importedEvents.length===1?'':'s'))}
function clearLocalData(){if(!window.confirm('Clear this device local events, tasks, and preferences?'))return;events=[];todos=[];birthday='';demoMode=false;view=window.matchMedia?.('(max-width: 760px)').matches?'agenda':'week';focusDate=atNoon(C.chicagoClock(new Date()).date);miniDate=new Date(focusDate);[DEMO_MODE_KEY,WELCOME_KEY,'illini-events','illini-todos','illini-view','illini-focus','illini-birthday'].forEach(key=>localStorage.removeItem(key));$('#dataDialog').close();render();toast('Local data cleared')}
function maybeShowWelcome(){if(currentAccount||hadDeviceDataAtBoot||localStorage.getItem(WELCOME_KEY))return;const dialog=$('#welcomeDialog');if(dialog&&!dialog.open)dialog.showModal()}
function chooseWelcome(mode){demoMode=mode==='demo';localStorage.setItem(DEMO_MODE_KEY,demoMode?'1':'0');localStorage.setItem(WELCOME_KEY,'1');if(!demoMode){events=[];todos=[]}$('#welcomeDialog').close();setPrivacyStatus();render();toast(demoMode?'Demo schedule loaded':'Empty calendar ready')}
function chooseLocalImport(){return new Promise(resolve=>{const dialog=$('#migrationDialog'),importBtn=$('#importLocalBtn'),freshBtn=$('#startFreshBtn');importBtn.onclick=()=>{dialog.close();resolve(true)};freshBtn.onclick=()=>{dialog.close();resolve(false)};dialog.showModal()})}
function continueWithoutAccount(message='Saved on this device · Sign in for cloud sync'){currentAccount=null;cloudReady=false;$('#authGate').hidden=true;$('#accountChip').hidden=true;setPrivacyStatus();setSyncStatus('Saved on this device');setView(view);checkSleepReminder();checkBirthday();maybeShowWelcome()}
async function bootstrapAccount(){
  try{
    const accountResponse=await apiFetch('/api/account',{cache:'no-store'});
    if(accountResponse.status===401){if(API_BASE)localStorage.removeItem(AUTH_TOKEN_KEY);continueWithoutAccount();return}
    if(!accountResponse.ok)throw new Error('Account service unavailable');
    currentAccount=(await accountResponse.json()).user;
    $('#accountName').textContent=currentAccount.email;$('#accountAvatar').textContent=(currentAccount.email[0]||'I').toUpperCase();$('#accountChip').hidden=false;
    const stateResponse=await apiFetch('/api/state',{cache:'no-store'});if(!stateResponse.ok)throw new Error('Schedule sync unavailable');const state=await stateResponse.json();
    const previousUser=localStorage.getItem('illini-last-user-id');
    if(state.exists){events=Array.isArray(state.events)?state.events:[];todos=Array.isArray(state.todos)?state.todos:[];if(['agenda','day','week','month','year'].includes(state.preferences?.view))view=state.preferences.view;if(/^\d{4}-\d{2}-\d{2}$/.test(state.preferences?.focus||'')){focusDate=atNoon(state.preferences.focus);miniDate=new Date(focusDate)}birthday=/^\d{4}-\d{2}-\d{2}$/.test(state.preferences?.birthday||'')?state.preferences.birthday:''}
    else {
      const mayImport=hadDeviceDataAtBoot&&(!previousUser||previousUser===currentAccount.id),importLocal=mayImport?await chooseLocalImport():false;
      if(!importLocal){events=sampleEvents();todos=[];focusDate=atNoon(C.chicagoClock(new Date()).date);miniDate=new Date(focusDate);view='week'}
    }
    localStorage.setItem('illini-last-user-id',currentAccount.id);cloudReady=true;$('#authGate').hidden=true;setPrivacyStatus();setSyncStatus(state.exists?'Synced across devices':'Creating cloud schedule…');setView(view);checkSleepReminder();checkBirthday();
  }catch(error){continueWithoutAccount('Saved on this device · Cloud sync unavailable');console.error(error)}
}
function beginAccountSignIn(event){event?.preventDefault();if(!API_BASE){location.href='/signin-with-chatgpt?return_to=/';return}const bridge=`${API_BASE}/auth-bridge.html?origin=${encodeURIComponent(location.origin)}`,popup=window.open(bridge,'illini-day-sign-in','popup,width=520,height=680');if(!popup)toast('Allow the sign-in pop-up, then try again.')}
window.addEventListener('message',event=>{if(!API_BASE)return;let backendOrigin;try{backendOrigin=new URL(API_BASE).origin}catch{return}if(event.origin!==backendOrigin||event.data?.type!=='illini-auth'||typeof event.data.token!=='string'||event.data.token.length<32)return;localStorage.setItem(AUTH_TOKEN_KEY,event.data.token);location.reload()});
$('#authButton').onclick=beginAccountSignIn;
$('#accountSignout').onclick=async event=>{event.preventDefault();if(!API_BASE){location.href='/signout-with-chatgpt?return_to=/';return}try{await apiFetch('/api/auth/logout',{method:'POST'})}catch{}localStorage.removeItem(AUTH_TOKEN_KEY);location.reload()};
function eventDate(e){return atNoon(e.date)}
function filtered(es){return es.filter(e=>filters.has(e.type))}
function updateHeader(){const label=view==='year'?String(focusDate.getFullYear()):view==='agenda'?'Agenda':focusDate.toLocaleDateString('en-US',{month:'long',year:'numeric'});$('#rangeTitle').textContent=label;const dayEvents=events.filter(e=>e.date===fmtDate(focusDate));if(view==='agenda'){const end=fmtDate(addDays(focusDate,13)),items=events.filter(e=>e.date>=fmtDate(focusDate)&&e.date<=end).length;$('#daySummary').textContent=fmtDate(focusDate)+' → '+end+' · '+items+' scheduled item'+(items===1?'':'s');return}if(view==='year'){$('#daySummary').textContent=events.filter(e=>e.date.startsWith(String(focusDate.getFullYear())+'-')).length+' scheduled items across the year';return}$('#daySummary').textContent=focusDate.toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'})+' · '+dayEvents.length+' item'+(dayEvents.length===1?'':'s')}
function syncTaskCompletionToEvents(){const status=new Map(todos.map(t=>[t.id,!!t.done]));events=events.map(e=>e.sourceTaskId&&status.has(e.sourceTaskId)?{...e,taskDone:status.get(e.sourceTaskId)}:e);todos=todos.map(t=>{const linked=events.filter(e=>e.sourceTaskId===t.id),scheduledSessions=linked.length;return {...t,scheduled:scheduledSessions>0,scheduledSessions,scheduledSessionIds:linked.map(e=>e.id)}})}
function render(){syncTaskCompletionToEvents();updateHeader();renderMini();if(view==='year')renderYear();else if(view==='month')renderMonth();else if(view==='day')renderDay();else if(view==='agenda')renderAgenda();else renderWeek();renderTodos();save();updateNowLine();updateInsight()}
function renderMini(){const y=miniDate.getFullYear(),m=miniDate.getMonth();$('#miniTitle').textContent=miniDate.toLocaleDateString('en-US',{month:'long',year:'numeric'});const first=new Date(y,m,1),start=new Date(y,m,1-first.getDay()),cells=[];for(let i=0;i<42;i++){const d=addDays(start,i),ds=fmtDate(d),cl=['mini-day'];if(d.getMonth()!==m)cl.push('other');if(ds===fmtDate(new Date()))cl.push('today');if(ds===fmtDate(focusDate))cl.push('selected');if(events.some(e=>e.date===ds))cl.push('has-events');if(C.isBirthdayDate(birthday,ds))cl.push('birthday-day');cells.push(`<button class="${cl.join(' ')}" data-date="${ds}" title="${C.isBirthdayDate(birthday,ds)?'Birthday':''}">${d.getDate()}${C.isBirthdayDate(birthday,ds)?'<span aria-hidden="true">🎂</span>':''}</button>`)}$('#miniGrid').innerHTML=cells.join('');$$('.mini-day').forEach(b=>b.onclick=()=>{focusDate=atNoon(b.dataset.date);render()})}
function eventButton(e,style=''){return `<button class="event-card ${COLORS[e.type]} ${e.taskDone?'task-complete':''}" data-event="${e.id}" style="${style}"><strong>${esc(e.title)}</strong><span>${e.taskDone?'✓ Completed · ':''}${niceTime(e.start)} · ${esc(e.place)}</span></button>`}
function nowLineHtml(ds){return ds===C.chicagoClock(new Date()).date?'<div class="now-line" data-now-line><span class="now-label"></span></div>':''}
function renderWeek(){$('#calendar').classList.remove('year-calendar');const mon=startWeek(focusDate),days=[0,1,2,3,4,5,6].map(n=>addDays(mon,n));let html='<div class="week-grid"><div class="week-head corner"></div>';days.forEach(d=>{const ds=fmtDate(d),today=ds===fmtDate(new Date());html+=`<div class="week-head ${today?'is-today':''} ${C.isBirthdayDate(birthday,ds)?'is-birthday':''}"><span class="dow">${d.toLocaleDateString('en-US',{weekday:'short'})}${C.isBirthdayDate(birthday,ds)?' 🎂':''}</span><span class="dom">${d.getDate()}</span></div>`});html+='<div class="time-col">';for(let h=7;h<24;h++)html+=`<div class="time-label">${h%12||12} ${h<12?'AM':'PM'}</div>`;html+='</div>';days.forEach(d=>{const ds=fmtDate(d),es=filtered(events.filter(e=>e.date===ds));html+=`<div class="day-col ${d.getDay()===0||d.getDay()===6?'weekend':''}" data-day="${ds}">`;es.forEach(e=>{const top=(C.mins(e.start)-DAY_START)/60*HOUR,height=Math.max(28,(C.mins(e.end)-C.mins(e.start))/60*HOUR-3);html+=eventButton(e,`top:${top}px;height:${height}px`)});html+=nowLineHtml(ds)+'</div>'});html+='</div>';$('#calendar').innerHTML=html;bindEvents()}
function renderDay(){$('#calendar').classList.remove('year-calendar');const ds=fmtDate(focusDate),es=filtered(events.filter(e=>e.date===ds));let html=`<div class="day-view"><div class="day-title">${focusDate.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}${C.isBirthdayDate(birthday,ds)?' · 🎂 Birthday':''}</div><div class="time-col">`;for(let h=7;h<24;h++)html+=`<div class="time-label">${h%12||12} ${h<12?'AM':'PM'}</div>`;html+=`</div><div class="day-col single" data-day="${ds}">`;es.forEach(e=>{const top=(C.mins(e.start)-DAY_START)/60*HOUR,height=Math.max(30,(C.mins(e.end)-C.mins(e.start))/60*HOUR-3);html+=eventButton(e,`top:${top}px;height:${height}px`)});html+=nowLineHtml(ds)+'</div></div>';$('#calendar').innerHTML=html;bindEvents()}
function renderAgenda(){$('#calendar').classList.remove('year-calendar');const start=atNoon(fmtDate(focusDate)),end=addDays(start,14),visible=filtered(events.filter(e=>e.date>=fmtDate(start)&&e.date<fmtDate(end))).sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start));if(!visible.length){$('#calendar').innerHTML='<div class="agenda-view"><div class="agenda-empty"><strong>No events in this window.</strong><span>Add an event or move the date range to see your schedule here.</span></div></div>';return}let html='<div class="agenda-view"><div class="agenda-intro"><span class="eyebrow">UP NEXT</span><strong>Your next two weeks</strong><span>Tap an item for Quick Look and walking time.</span></div>';let current='';visible.forEach((event,index)=>{if(event.date!==current){current=event.date;const count=events.filter(item=>item.date===event.date).length;html+='<section class="agenda-day"><header><strong>'+atNoon(event.date).toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'})+'</strong><span>'+count+' item'+(count===1?'':'s')+'</span></header>'}html+='<button class="agenda-event '+COLORS[event.type]+'" data-event="'+esc(event.id)+'"><span class="agenda-time">'+niceTime(event.start)+'<small>'+niceTime(event.end)+'</small></span><span class="agenda-details"><strong>'+esc(event.title)+'</strong><span>'+esc(event.place)+'</span></span><span class="agenda-chevron">›</span></button>';const next=visible[index+1];if(!next||next.date!==current)html+='</section>'});html+='</div>';$('#calendar').innerHTML=html;bindEvents()}
function renderMonth(){$('#calendar').classList.remove('year-calendar');const y=focusDate.getFullYear(),m=focusDate.getMonth(),first=new Date(y,m,1),start=new Date(y,m,1-first.getDay());let html='<div class="month-grid">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="month-weekday">${x}</div>`).join('');for(let i=0;i<42;i++){const d=addDays(start,i),ds=fmtDate(d),isBirthday=C.isBirthdayDate(birthday,ds),es=filtered(events.filter(e=>e.date===ds)).slice(0,isBirthday?3:4);html+=`<div class="month-cell ${d.getMonth()!==m?'other':''} ${isBirthday?'birthday-cell':''}" data-date="${ds}"><div class="month-date ${ds===fmtDate(new Date())?'today':''}">${d.getDate()}</div>${isBirthday?'<div class="birthday-chip">🎂 Birthday</div>':''}${es.map(e=>`<button class="month-event event-card ${COLORS[e.type]}" data-event="${e.id}">${esc(e.title)}</button>`).join('')}${events.filter(e=>e.date===ds).length>(isBirthday?3:4)?'<small>more…</small>':''}</div>`}html+='</div>';$('#calendar').innerHTML=html;bindEvents();$$('.month-cell').forEach(c=>c.ondblclick=()=>{focusDate=atNoon(c.dataset.date);setView('day')})}
function renderYear(){const calendar=$('#calendar'),year=focusDate.getFullYear(),weekdays=['S','M','T','W','T','F','S'];calendar.classList.add('year-calendar');let html='<div class="year-grid">';for(let month=0;month<12;month++){const first=new Date(year,month,1),days=new Date(year,month+1,0).getDate();html+=`<section class="year-month"><h3>${first.toLocaleDateString('en-US',{month:'long'})}</h3><div class="year-weekdays">${weekdays.map(x=>`<span>${x}</span>`).join('')}</div><div class="year-days">${'<span></span>'.repeat(first.getDay())}`;for(let day=1;day<=days;day++){const d=new Date(year,month,day,12),ds=fmtDate(d),count=events.filter(e=>e.date===ds).length,isBirthday=C.isBirthdayDate(birthday,ds),today=ds===C.chicagoClock(new Date()).date;html+=`<button data-year-date="${ds}" class="year-day ${count?'has-items':''} ${isBirthday?'birthday-day':''} ${today?'today':''}" title="${isBirthday?'Birthday · ':''}${count} scheduled item${count===1?'':'s'}"><span>${day}</span>${isBirthday?'<b aria-label="Birthday">🎂</b>':count?`<i>${count}</i>`:''}</button>`}html+='</div></section>'}html+='</div>';calendar.innerHTML=html;$$('[data-year-date]').forEach(button=>button.onclick=()=>{focusDate=atNoon(button.dataset.yearDate);miniDate=new Date(focusDate);setView('day')})}
