function openEvent(defaults={}){const f=$('#eventForm');f.reset(),date=defaults.date||fmtDate(focusDate),weekly=!!defaults.weekly;editingEventId=defaults.id&&events.some(e=>e.id===defaults.id)?defaults.id:null;$('#eventDialogTitle').textContent=editingEventId?'Edit schedule item':weekly?'Add a weekly event':'Add an event';f.elements.date.value=date;f.elements.start.value=defaults.start||'14:00';f.elements.end.value=defaults.end||'15:00';f.elements.title.value=defaults.title||'';f.elements.place.value=defaults.place||'';f.elements.type.value=defaults.type||'Campus';f.elements.note.value=defaults.note||'';f.elements.url.value=defaults.url||'';$('#repeatOptions').classList.toggle('hidden',!weekly||!!editingEventId);if(weekly&&!editingEventId){const start=atNoon(date),until=addDays(start,112);f.elements.repeatUntil.value=fmtDate(until);f.elements.repeatUntil.min=date;const selected=start.getDay();$$('[name="repeatDay"]').forEach(x=>x.checked=Number(x.value)===selected)}openDialog('eventDialog')}
function syncTaskDetailsToEvents(task){if(!task)return;events=events.map(event=>event.sourceTaskId===task.id?C.syncDetailsFromTask(task,event):event)}
