async function submitCandidate(cand,options={}){const conflicts=C.conflicts(cand,events);for(const issue of conflicts.filter(x=>x.kind==='travel')){const before=issue.event.end<=cand.start,from=before?issue.event.place:cand.place,to=before?cand.place:issue.event.place,route=await walkInfo(from,to);issue.walk=route.minutes;issue.googleUrl=route.googleUrl}const active=conflicts.filter(x=>x.kind==='overlap'||x.walk>x.gap);if(active.length){pending=cand;pendingResume=options.resumeOnCancel?cand:null;conflictItems=active;$('#conflictTitle').textContent=active.some(x=>x.kind==='overlap')?'Your schedule has a conflict':'Not enough walking time';$('#conflictText').textContent=active.some(x=>x.kind==='overlap')?'Choose which commitment belongs on your calendar.':'The pedestrian route estimate does not leave enough time.';$('#conflictCards').innerHTML=active.map(x=>`<div class="conflict-item"><strong>${esc(x.event.title)}</strong><span>${niceTime(x.event.start)}–${niceTime(x.event.end)} · ${esc(x.event.place)}</span><span>${x.kind==='travel'?`Needs ${x.walk} min walking; only ${x.gap} min available · <a target="_blank" rel="noopener" href="${esc(x.googleUrl)}">Google Maps ↗</a>`:`Overlaps by ${x.minutes} min`}</span></div>`).join('');openDialog('conflictDialog');return false}pendingResume=null;const updated=events.some(e=>e.id===cand.id);upsertEvents(cand);render();toast(updated?'Schedule item updated':'Added to your schedule');return true}
