function taskPlanLabel(t){if(!Number(t.duration))return 'Reminder only';return t.completionMode==='split'?`${t.sessionCount} × ${t.sessionDuration} min`:`${t.duration} min`}
function taskCard(t){const scheduledLabel=t.scheduled?(t.completionMode==='split'?`<br>✓ ${t.scheduledSessions||0}/${t.sessionCount||0} sessions on calendar`:'<br>✓ Work session scheduled'):'';return `<article class="todo-item ${t.done?'done':''} ${t.source==='canvas'?'canvas-task':''}"><input class="todo-check" type="checkbox" aria-label="Mark ${esc(t.title)} ${t.done?'pending':'complete'}" data-todo-check="${t.id}" ${t.done?'checked':''}><div>${t.source==='canvas'?`<span class="canvas-badge">CANVAS · ${esc(t.canvasArea||'TO DO')}</span>`:''}<h3>${esc(t.title)}</h3><p>${t.source==='canvas'?`${esc(t.course||'Canvas')} · `:''}${esc(t.kind)} · ${taskPlanLabel(t)} · ${esc(t.place||'Anywhere')}<br><span class="${new Date(t.deadline)-Date.now()<48*3600000&&!t.done?'todo-due-soon':''}">Due ${new Date(t.deadline).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</span>${scheduledLabel}</p></div><button data-todo-detail="${t.id}">Details</button></article>`}
